import{_ as s,o as a,c as n,a3 as i}from"./chunks/framework.DH50UWNB.js";const u=JSON.parse(`{"title":"Sign-up and accounts","description":"Who can create an account on your Wake server, invitation-only sign-up, sign-up limits, and the free plan's accounts with wake-server accounts.","frontmatter":{"description":"Who can create an account on your Wake server, invitation-only sign-up, sign-up limits, and the free plan's accounts with wake-server accounts."},"headers":[],"relativePath":"run/sign-up.md","filePath":"run/sign-up.md","lastUpdated":1794486787000}`),t={name:"run/sign-up.md"};function o(r,e,c,d,h,l){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="sign-up-and-accounts" tabindex="-1">Sign-up and accounts <a class="header-anchor" href="#sign-up-and-accounts" aria-label="Permalink to &quot;Sign-up and accounts&quot;">​</a></h1><p>Who can create an account, and how to manage the accounts with <code>wake-server accounts</code>. On a local install anyone who reaches the server (only this machine) can create an account, up to the free plan&#39;s 3 people. A <a href="/wake-dist/docs/run/install-options#your-first-account">domain install</a> closes sign-up to invitations and gives you a link for the first account. You can close sign-up yourself, and free a place by disabling an account.</p><h2 id="the-first-account" tabindex="-1">The first account <a class="header-anchor" href="#the-first-account" aria-label="Permalink to &quot;The first account&quot;">​</a></h2><p>A domain install writes these lines to <code>.env</code> and prints <code>https://&lt;host&gt;/sign-up?setup=&lt;token&gt;</code> once:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SIGN_UP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">invitation</span></span>
<span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SETUP_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">64</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> hexadecimal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> character</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>While the server has no account, only a password sign-up through that link creates one; any other sign-up answers <code>403</code> <code>setup_token_required</code> and creates no user, and a first account through a <a href="/wake-dist/docs/run/sign-in-providers">sign-in provider</a> is refused the same way. Once the first account exists the token has no effect. The sign-up screen removes the token from the address bar as it opens, so it stays out of the browser&#39;s history.</p><p>Lost the link? Build it from the <code>SETUP_TOKEN</code> line of <code>.env</code>. To use this on an installation made before it, add a <code>SETUP_TOKEN</code> of 32 to 256 characters (<code>openssl rand -hex 32</code>) next to <code>SIGN_UP=invitation</code> and run <code>wake-server start</code> before anyone signs up.</p><h2 id="only-by-invitation" tabindex="-1">Only by invitation <a class="header-anchor" href="#only-by-invitation" aria-label="Permalink to &quot;Only by invitation&quot;">​</a></h2><p>Add this line to the installation&#39;s <code>.env</code>, then run <code>wake-server start</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SIGN_UP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">invitation</span></span></code></pre></div><p>The first account of a server without users is still created freely, unless <code>.env</code> also has a <code>SETUP_TOKEN</code> (see <a href="#the-first-account">The first account</a>), so you can set it before your first sign-up. After that, only someone with a pending <a href="/wake-dist/docs/use/workspaces#invite-people">invitation</a> creates an account, joining its workspace in the same step.</p><ul><li>A refused password sign-up answers <code>403</code> <code>sign_up_closed</code>; a new account through a <a href="/wake-dist/docs/run/sign-in-providers">sign-in provider</a> is refused the same way and creates no user.</li><li>Existing users keep signing in, by password or with a linked provider, and keep linking providers.</li><li>The sign-up screen says that sign-up needs an invitation.</li></ul><p>An invitation link works with sign-in providers too: when the provider&#39;s sign-in creates a new account, it joins the invitation&#39;s workspace in the same step; an account that already exists just signs in and the invitation stays pending. An invitation revoked or used before the sign-in finishes creates no account (<code>invitation_not_found</code>).</p><p>Remove the line, or set it to <code>open</code>, and run <code>wake-server start</code> to open sign-up again. Any other value stops the server at start.</p><h2 id="sign-up-limits" tabindex="-1">Sign-up limits <a class="header-anchor" href="#sign-up-limits" aria-label="Permalink to &quot;Sign-up limits&quot;">​</a></h2><p>Every new account counts against one budget per client address, 10 an hour, whether it is created by password or through a provider; signing in to an existing account never counts. Past it, password sign-up and GitHub answer <code>429</code> <code>rate_limited</code> with <code>Retry-After</code>, and the other providers send the browser back with the error <code>rate_limited</code>.</p><h2 id="free-plan-accounts" tabindex="-1">Free plan accounts <a class="header-anchor" href="#free-plan-accounts" aria-label="Permalink to &quot;Free plan accounts&quot;">​</a></h2><p>The free plan allows 3 people in all for you and your company, however many installations you run; see <a href="/wake-dist/docs/reference/license#the-free-plan">License</a>. Each installation holds that limit itself: at most 3 active accounts, each used by one person, and each signed in on at most 3 browsers (a fourth sign-in signs out the oldest). Agents, personal access tokens and OAuth clients never count. A fourth sign-up, by password, invitation or sign-in provider, is refused with <code>403</code> <code>people_limit_reached</code> and <code>details.limit</code> <code>3</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>This installation already has the 3 people the free plan allows; whoever runs it can free a place with \`wake-server accounts disable &lt;email&gt;\`</span></span></code></pre></div><p>Removing someone from a workspace frees no place: their account stays active. Only disabling the account does. <strong>Members</strong> in the web app shows how many of the 3 places the installation uses. See the <a href="/wake-dist/docs/reference/license">License</a>.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> accounts</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> accounts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vera@example.com</span></span>
<span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> accounts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vera@example.com</span></span></code></pre></div><p><code>wake-server accounts</code> lists every account, one line each with the email, the name and <code>active</code> or <code>disabled</code>, then <code>People: &lt;n&gt; of 3 (free plan)</code>.</p><ul><li><code>disable</code> frees a place: the account cannot sign in any more, and its sessions, tokens and connected agents are signed out (the <a href="/wake-dist/docs/use/audit-log">audit log</a> records the revoked tokens with the cause <code>account_disabled</code>). Its tasks, events, memberships and audit entries are kept, and its email stays taken.</li><li><code>enable</code> gives the account back while fewer than 3 accounts are active; its old sessions and tokens stay revoked.</li></ul><p>Emails are matched as sign-in matches them, whatever their case. Each command runs while Wake keeps serving and prints one line saying what it did; disabling an account already disabled, or enabling an active one, says so and exits <code>0</code>. An unknown email, or enabling with no free place, exits <code>1</code> and changes nothing; a missing or extra argument exits <code>2</code> with the usage. They run inside the server&#39;s container, so Wake must be running: otherwise they exit <code>1</code> naming <code>wake-server start</code>.</p>`,24)])])}const k=s(t,[["render",o]]);export{u as __pageData,k as default};
